.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  gap: 1rem;
}

.card {
  padding: 1rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.75rem;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: #ffffff;
  border-bottom: 1px solid #e2e8f0;
  padding: 0.75rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

:root {
  --color-bg: #ffffff;
  --color-surface: #f8fafc;
  --color-text: #1e293b;
  --color-muted: #64748b;
  --color-accent: #2563eb;
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-bg: #0f172a;
    --color-surface: #1e293b;
    --color-text: #f1f5f9;
    --color-muted: #94a3b8;
    --color-accent: #60a5fa;
  }
}

.btn {
  display: inline-flex;
  align-items: center;
  padding: 0.5rem 1.25rem;
  border-radius: 0.5rem;
  background-color: #2563eb;
  color: #ffffff;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: transform 150ms ease, box-shadow 150ms ease;
}

.btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.35);
}

.btn:active {
  transform: translateY(0);
  box-shadow: none;
}

.centered-container {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@keyframes shimmer {
  from { background-position: -200% 0; }
  to   { background-position:  200% 0; }
}

.skeleton {
  background: linear-gradient(
    90deg,
    #e2e8f0 25%,
    #f1f5f9 50%,
    #e2e8f0 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
  border-radius: 0.25rem;
}

.two-col {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

@media (max-width: 640px) {
  .two-col {
    grid-template-columns: 1fr;
  }
}

.badge-wrapper {
  position: relative;
  display: inline-flex;
}

.badge {
  position: absolute;
  top: -0.5rem;
  right: -0.5rem;
  min-width: 1.25rem;
  height: 1.25rem;
  padding: 0 0.3rem;
  border-radius: 9999px;
  background-color: #ef4444;
  color: #ffffff;
  font-size: 0.7rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.layout {
  display: grid;
  grid-template-areas:
    'sidebar main';
  grid-template-columns: 240px 1fr;
  gap: 1.5rem;
  min-height: 100vh;
}

.sidebar { grid-area: sidebar; }
.main    { grid-area: main; }

@media (max-width: 768px) {
  .layout {
    grid-template-areas:
      'main'
      'sidebar';
    grid-template-columns: 1fr;
  }
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}

.accordion-content.open {
  max-height: 500px;
}

.tag {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  background-color: #dbeafe;
  color: #1d4ed8;
  font-size: 0.8125rem;
  font-weight: 500;
}

.tag__remove {
  display: flex;
  align-items: center;
  cursor: pointer;
  opacity: 0.6;
  transition: opacity 120ms;
}

.tag__remove:hover { opacity: 1; }

.modal-overlay {
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 200;
}

.modal {
  background: #ffffff;
  border-radius: 0.75rem;
  padding: 2rem;
  max-width: 32rem;
  width: 90%;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.tooltip-wrapper {
  position: relative;
  display: inline-block;
}

.tooltip-wrapper::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: calc(100% + 6px);
  left: 50%;
  transform: translateX(-50%);
  background: #1e293b;
  color: #f1f5f9;
  font-size: 0.75rem;
  padding: 0.25rem 0.6rem;
  border-radius: 0.375rem;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transition: opacity 150ms;
}

.tooltip-wrapper:hover::after { opacity: 1; }

.focusable:focus { outline: none; }

.focusable:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 3px;
  border-radius: 0.25rem;
}

.scroll-cards {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding-bottom: 0.5rem;
}

.scroll-cards__item {
  flex: 0 0 280px;
  scroll-snap-align: start;
}

@keyframes stripes {
  from { background-position: 0 0; }
  to   { background-position: 2rem 0; }
}

.progress-track {
  background: #e2e8f0;
  border-radius: 9999px;
  overflow: hidden;
  height: 1rem;
}

.progress-fill {
  height: 100%;
  background: repeating-linear-gradient(
    45deg,
    #3b82f6,
    #3b82f6 0.75rem,
    #60a5fa 0.75rem,
    #60a5fa 1.5rem
  );
  background-size: 2rem 2rem;
  animation: stripes 0.8s linear infinite;
  border-radius: 9999px;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  list-style: none;
  padding: 0;
  margin: 0;
  font-size: 0.875rem;
}

.breadcrumb li + li::before {
  content: '›';
  color: #94a3b8;
  margin-right: 0.25rem;
}

.breadcrumb a {
  color: #2563eb;
  text-decoration: none;
}

.breadcrumb a:hover { text-decoration: underline; }

.breadcrumb li:last-child { color: #64748b; }

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.data-table th {
  text-align: left;
  padding: 0.75rem 1rem;
  background-color: #f8fafc;
  border-bottom: 2px solid #e2e8f0;
  font-weight: 600;
  color: #475569;
}

.data-table td {
  padding: 0.6875rem 1rem;
  border-bottom: 1px solid #e2e8f0;
}

.data-table tbody tr:nth-child(even) { background-color: #f8fafc; }
.data-table tbody tr:hover           { background-color: #eff6ff; }

.hero {
  position: relative;
  min-height: 60vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background-image: url('hero.jpg');
  background-size: cover;
  background-position: center;
  color: #ffffff;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.55);
}

.hero__content {
  position: relative;
  z-index: 1;
  max-width: 42rem;
  padding: 2rem;
}
